`polyline` with tapering:

```js
function polyline(ctx, pts, w0, w1, c, out = OUT) {
  const n = pts.length - 1;
  // outline pass
  for (let pass=0; pass<2; pass++){
    const grow = pass===0 ? 2 : 0;
    const col = pass===0 ? out : c;
    for (let i=0;i<n;i++){
      const [x1,y1]=pts[i], [x2,y2]=pts[i+1];
      const t0=i/n, t1=(i+1)/n;
      const wa = (w0+(w1-w0)*t0) + grow;
      const wb = (w0+(w1-w0)*t1) + grow;
      // draw several samples between points
      const steps = Math.max(1, Math.ceil(Math.hypot(x2-x1,y2-y1)));
      for (let s=0;s<=steps;s++){
        const t=s/steps;
        const x=x1+(x2-x1)*t, y=y1+(y2-y1)*t;
        const w=wa+(wb-wa)*t;
        px(ctx, x-w/2, y-w/2, w, w, col);
      }
    }
  }
}
```
Squares overlapping produce chunky limbs. Good.

`ell` uses `ctx.fillRect` spans. Note rounding center coords to integers to keep pixel alignment: `cx=Math.round(cx); cy=Math.round(cy)`.

`tri` with path:
```js
function tri(ctx,x1,y1,x2,y2,x3,y3,c,out=OUT,stroke=2){
 ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.lineTo(x3,y3); ctx.closePath();
 ctx.fillStyle=c; ctx.fill();
 if(out){ ctx.strokeStyle=out; ctx.lineWidth=stroke; ctx.stroke(); }
}
```
Stroke will cover edges, acceptable.

Star path:
```js
function star(ctx,cx,cy,R,r,points,rot,c,out){
 ctx.beginPath();
 for(let i=0;i<points*2;i++){
  const ang = rot + i*Math.PI/points - Math.PI/2;
  const rad = i%2? r:R;
  const x=cx+Math.cos(ang)*rad, y=cy+Math.sin(ang)*rad;
  i?ctx.lineTo(x,y):ctx.moveTo(x,y);
 }
 ctx.closePath(); ctx.fillStyle=c; ctx.fill(); ctx.strokeStyle=out; ctx.lineWidth=2.5; ctx.stroke();
}
```

