function tentacle(ctx, x0,y0,x1,y1, w0,w1, color, t, phase, sway=3){
  const pts=[];
  const n=6;
  for(let i=0;i<=n;i++){
    const q=i/n;
    const x = x0 + (x1-x0)*q + Math.sin(t*0.08 + phase + q*2.5)*sway*q;
    const y = y0 + (y1-y0)*q;
    pts.push([x,y]);
  }
  polyline(ctx, pts, w0,w1,color);
}
```
