```js
function drawClaw(ctx,x,y,size,open,color,out){
  // base ellipse
  ellO(ctx,x,y,size*0.6,size*0.5,color,out);
  // upper finger
  ellO(ctx,x+size*0.35,y-size*0.45,size*0.55,size*0.22,color,out);
  // lower finger
  ellO(ctx,x+size*0.35,y+size*0.3,size*0.5,size*0.2,color,out);
  // notch dark wedge
  tri(ctx, x+size*0.15,y, x+size*1.0,y-size*0.2*(1+open), x+size*1.0,y+size*0.2*(1+open), out);
}
```
