  f.animT++;
  if (f.state === 'ko') { ko physics; f.prevIn={...inp}; return; }
  const roundOver = game.roundOver;
  const canAct = !roundOver && game.fightLock <= 0 && f.hitstun <= 0 && f.blockstun <= 0 && !f.attack;

  if (f.hitstun > 0) f.hitstun--;
  if (f.blockstun > 0) f.blockstun--;
  if (f.invuln > 0) f.invuln--;

  if (!roundOver && f.hitstun <= 0 && !f.attack) f.facing = opp.x >= f.x ? 1 : -1;
  if (roundOver) f.facing = opp.x >= f.x ? 1 : -1;

  f.blocking = !roundOver && f.hitstun <= 0 && inp.block && f.onGround && !f.attack;
  f.crouching = !roundOver && f.hitstun <= 0 && inp.down && f.onGround && !f.attack && !f.blocking;

  const busy = f.hitstun > 0 || f.blockstun > 0 || f.attack || roundOver;
  // movement
  let dir = 0;
  if (!busy && !f.blocking) dir = (inp.right?1:0)-(inp.left?1:0);
  if (!busy && !f.blocking) {
    if (dir !== 0) {
      const mul = (dir === f.facing ? 1 : 0.8) * (f.onGround ? 1 : 0.92);
      f.vx = dir * f.char.speed * mul;
      if (f.onGround) f.state = 'walk';
    } else if (f.onGround) {
      f.vx *= 0.6;
      if (!f.attack) f.state = 'idle';
    }
  } else if (f.onGround && f.hitstun <= 0) {
    f.vx *= 0.82;
