    f.vy = -f.char.jump; f.onGround = false; f.state='jump'; audio.jump();
    spawnParticles(f.x, GROUND, '#d8c8a8', 4, {spread:1, up:1, life:14, size:1});
  }

  // start attacks
  if (!busy && !f.blocking && !f.crouching) { ... }
