  game.result={winner, winnerIdx: winner.player, rounds:[f1.roundsWon, f2.roundsWon], perfect: winner.hp >= winner.maxHp};
  game.resultIndex=0;
  game.particles=[];
  audio.stopTrack(); audio.fanfare();
}
