function updateCPU(game, f, opp){
  const inp = game.cpuInput; // object reset by game
  const ai=game.ai;
  if (game.roundOver || game.fightLock>0) return;
  const dist=Math.abs(opp.x-f.x);
  ai.timer--;
  if (ai.timer<=0){
    ai.timer = AI[game.diff].react + Math.random()*20;
    const r=Math.random();
    if (dist>140){ ai.action = r<0.2?'special': r<0.35?'jumpIn':'approach'; }
    else if (dist>70){ ai.action = r<0.4?'approach': r<0.55?'special': r<0.7?'jumpIn':'block'; }
    else { ai.action = r<0.5?'attack': r<0.65?'block': r<0.8?'retreat':'attack'; }
    ai.actionT = 10+Math.random()*18;
  }
  ai.actionT--;
  // block reaction
  if (opp.attack && dist<95 && Math.random()<AI[game.diff].block*0.15) { ai.action='block'; ai.actionT=Math.max(ai.actionT,8); }
  const toward = Math.sign(opp.x-f.x)||1;
  const hold=(d)=>{ if(d>0) inp.right=true; else if(d<0) inp.left=true; };
  switch(ai.action){
    case 'approach': hold(toward); if (Math.random()<0.004) inp.up=true; break;
    case 'retreat': hold(-toward); break;
    case 'block': inp.block=true; break;
    case 'jumpIn': if (f.onGround && ai.actionT>10) inp.up=true; hold(toward); if(!f.onGround && dist<90 && Math.random()<0.15) inp.kick=true; break;
    case 'attack':
      if (dist<85){ if (Math.random()<0.12){ if (Math.random()<0.6) inp.punch=true; else inp.kick=true; } }
      else hold(toward);
      break;
    case 'special':
      if (f.meter>=50 && dist<180){ inp.special=true; ai.action='wait'; }
      else hold(toward);
      break;
    case 'wait': break;
  }
  if (f.meter>=100 && dist<200 && Math.random()<0.01) inp.special=true;
}
