import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const URL = 'http://localhost:3002/';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(20000);
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

const res = await page.goto(URL, { waitUntil: 'load' });
console.log('HTTP', res.status());
await page.waitForTimeout(800);

const state = () => page.evaluate(() => {
  const g = window.__cc.game;
  return {
    scene: g.scene, paused: g.paused, mode: g.mode, round: g.round,
    picked: g.select.picked, stage: g.stage,
    fighters: g.fighters.map((f) => ({
      name: f.def?.name, x: Math.round(f.x), y: Math.round(f.y),
      hp: Math.round(f.hp), meter: Math.round(f.meter), state: f.state,
      facing: f.facing, wins: f.wins,
    })),
    result: g.result,
    timer: Math.round(g.timer),
  };
});

// 1. Title
console.log('TITLE:', JSON.stringify(await state()));
await page.screenshot({ path: '/tmp/opencode/v-title.png' });

// 2. Navigate title menu with keyboard
await page.keyboard.press('ArrowDown');
await page.keyboard.press('ArrowDown');
let s = await state();
console.log('MENU AFTER 2 DOWN (expect 2):', await page.evaluate(() => window.__cc.game.menuIndex));

// open how-to-play
