const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(500);
await page.evaluate(() => window.__cc.startMatchup(0, 4, 'cpu'));
// wait out the intro
await page.waitForTimeout(2600);
console.log('lock:', await page.evaluate(() => window.__cc.game.fightLock));
await page.keyboard.down('KeyD');
await page.waitForTimeout(100);
console.log('keys while held:', await page.evaluate(() => [...window.__cc.game.keys]));
console.log('input:', await page.evaluate(() => {
  const g = window.__cc.game;
  return { x: g.fighters[0].x, vx: g.fighters[0].vx, state: g.fighters[0].state, hitstun: g.fighters[0].hitstun, blocking: g.fighters[0].blocking, crouch: g.fighters[0].crouching };
}));
await page.waitForTimeout(800);
console.log('after hold:', await page.evaluate(() => ({ x: window.__cc.game.fighters[0].x, vx: window.__cc.game.fighters[0].vx, state: window.__cc.game.fighters[0].state })));
await page.keyboard.up('KeyD');

// try lowercase
await page.keyboard.down('d');
await page.waitForTimeout(100);
console.log('keys lowercase:', await page.evaluate(() => [...window.__cc.game.keys]));
await page.waitForTimeout(500);
console.log('after lowercase:', await page.evaluate(() => ({ x: window.__cc.game.fighters[0].x, state: window.__cc.game.fighters[0].state })));
await page.keyboard.up('d');

// punch
await page.keyboard.down('j');
await page.waitForTimeout(80);
console.log('punch keys:', await page.evaluate(() => [...window.__cc.game.keys]));
console.log('punch state:', await page.evaluate(() => ({ state: window.__cc.game.fighters[0].state, attack: window.__cc.game.fighters[0].attack?.name, meter: window.__cc.game.fighters[0].meter })));
