const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
const res = await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(600);
console.log('HTTP', res.status());

const snap = () => page.evaluate(() => {
  const g = window.__cc.game;
  return {
    scene: g.scene, paused: g.paused, mode: g.mode, round: g.round, stage: g.stage,
    lock: g.fightLock, roundOver: g.roundOver, result: g.result && { winner: g.result.winner.char.name, rounds: g.result.rounds, perfect: g.result.perfect },
    fighters: g.fighters.map((f) => ({ name: f.char.name, x: Math.round(f.x), hp: Math.round(f.hp), meter: Math.round(f.meter), state: f.state, wins: f.roundsWon })),
  };
});

const waitLock = async () => {
  await page.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });
};

// ---- roster ----
const roster = await page.evaluate(async () => {
  const m = await import('./js/characters.js');
  return m.ROSTER.map((r) => `${r.name} (${r.species})`);
});
console.log('ROSTER', roster.length, '=>', roster.join(' | '));

// ---- title & howto ----
await page.screenshot({ path: '/tmp/opencode/v-title.png' });
await page.keyboard.press('ArrowDown');
await page.keyboard.press('ArrowDown');
await page.keyboard.press('Enter');
await page.waitForTimeout(150);
console.log('HOWTO', await page.evaluate(() => window.__cc.game.howto));
await page.screenshot({ path: '/tmp/opencode/v-howto.png' });
await page.keyboard.press('Escape');

// ---- local controlled combat ----
await page.evaluate(() => window.__cc.startMatchup(0, 4, 'local'));
await waitLock();
console.log('LOCAL START', JSON.stringify(await snap()));

// P1 move right
const x0 = (await snap()).fighters[0].x;
await page.keyboard.down('KeyD');
await page.waitForFunction((x) => window.__cc.game.fighters[0].x > x + 15, x0, { timeout: 15000 });
await page.keyboard.up('KeyD');
console.log('P1 MOVED', x0, '->', (await snap()).fighters[0].x);

// P2 move left
const p2x = (await snap()).fighters[1].x;
await page.keyboard.down('ArrowLeft');
await page.waitForFunction((x) => window.__cc.game.fighters[1].x < x - 15, p2x, { timeout: 15000 });
await page.keyboard.up('ArrowLeft');
console.log('P2 MOVED', p2x, '->', (await snap()).fighters[1].x);

// jump
const y0 = (await snap()).fighters[0].x;
const yBefore = await page.evaluate(() => window.__cc.game.fighters[0].y);
await page.keyboard.press('KeyW');
await page.waitForFunction((y) => window.__cc.game.fighters[0].y < y - 20, yBefore, { timeout: 10000 });
console.log('JUMP WORKS, y', Math.round(yBefore), '->', Math.round(await page.evaluate(() => window.__cc.game.fighters[0].y)));
await page.waitForFunction((y) => window.__cc.game.fighters[0].y >= y - 1, yBefore, { timeout: 10000 });

// place close, punch
await page.evaluate(() => {
  const g = window.__cc.game;
  g.fighters[0].x = 210; g.fighters[1].x = 245;
  g.fighters[0].facing = 1; g.fighters[1].facing = -1;
});
const hpBefore = (await snap()).fighters[1].hp;
await page.keyboard.press('KeyJ');
await page.waitForFunction((hp) => window.__cc.game.fighters[1].hp < hp, hpBefore, { timeout: 10000 }).catch(() => {});
const afterPunch = await snap();
console.log('PUNCH: opp hp', hpBefore, '->', afterPunch.fighters[1].hp, 'P1 meter', afterPunch.fighters[0].meter);
await page.screenshot({ path: '/tmp/opencode/v-combat.png' });

// special
const meterBefore = afterPunch.fighters[0].meter;
await page.evaluate(() => { const g = window.__cc.game; g.fighters[0].x = 210; g.fighters[1].x = 250; g.fighters[0].meter = 50; });
await page.keyboard.press('KeyU');
await page.waitForFunction(() => window.__cc.game.fighters[0].state === 'attack' || window.__cc.game.projectiles.length > 0, null, { timeout: 10000 }).catch(() => {});
console.log('SPECIAL state:', await page.evaluate(() => ({ state: window.__cc.game.fighters[0].state, attack: window.__cc.game.fighters[0].attack?.name, projectiles: window.__cc.game.projectiles.length })));

// block test: P2 holds block, P1 punches
await page.evaluate(() => { const g = window.__cc.game; g.fighters[0].x = 210; g.fighters[1].x = 245; g.fighters[0].state='idle'; g.fighters[0].attack=null; g.fighters[0].hitstun=0; g.fighters[1].hp = g.fighters[1].maxHp; g.fighters[1].hitstun=0; g.fighters[1].state='idle'; });
await page.keyboard.down('Slash');
await page.waitForTimeout(150);
const blockState = await page.evaluate(() => window.__cc.game.fighters[1].blocking);
await page.keyboard.press('KeyJ');
await page.waitForTimeout(500);
console.log('BLOCKING ACTIVE:', blockState);
await page.keyboard.up('Slash');

// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('PAUSE TOGGLE:', (await snap()).paused);
await page.screenshot({ path: '/tmp/opencode/v-pause.png' });
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('RESUME TOGGLE:', (await snap()).paused);

// ---- CPU AI match ----
await page.evaluate(() => window.__cc.startMatchup(5, 9, 'cpu'));
await waitLock();
const aiStart = await snap();
await page.waitForTimeout(4000);
const aiEnd = await snap();
console.log('CPU AI moved/attacked:', aiStart.fighters[1].x, '->', aiEnd.fighters[1].x, '| P1 hp', aiStart.fighters[0].hp, '->', aiEnd.fighters[0].hp, '| timer', aiEnd.lock);
await page.screenshot({ path: '/tmp/opencode/v-fight.png' });

// ---- force rounds to result ----
async function winRound() {
  await page.evaluate(() => {
    const g = window.__cc.game;
    g.fighters[0].hp = g.fighters[0].maxHp;
    g.fighters[1].hp = 10;
    g.timer = 1;
  });
  await page.waitForFunction(() => window.__cc.game.roundOver, null, { timeout: 20000 });
  await page.evaluate(() => { window.__cc.game.roundOverT = 117; });
  await page.waitForFunction(() => window.__cc.game.roundOverT !== 117 || window.__cc.game.scene === 'result', null, { timeout: 20000 }).catch(() => {});
}
await winRound();
await page.waitForFunction(() => window.__cc.game.round === 2 || window.__cc.game.scene === 'result', null, { timeout: 20000 });
console.log('ROUND 2', JSON.stringify(await snap()));
await page.waitForFunction(() => window.__cc.game.fightLock === 0 || window.__cc.game.scene === 'result', null, { timeout: 60000 });
await winRound();
await page.waitForFunction(() => window.__cc.game.scene === 'result', null, { timeout: 20000 });
const finalState = await snap();
console.log('RESULT', JSON.stringify(finalState));
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/v-result.png' });
await page.keyboard.press('ArrowRight');
console.log('RESULT INDEX:', await page.evaluate(() => window.__cc.game.resultIndex));

// ---- mobile / touch ----
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
mob.setDefaultTimeout(30000);
mob.on('pageerror', (e) => errors.push('MOBILE PAGEERROR: ' + e.message));
await mob.goto('http://localhost:3002/?touch=1', { waitUntil: 'load' });
await mob.waitForTimeout(600);
await mob.evaluate(() => window.__cc.startMatchup(1, 6, 'local'));
await mob.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });
const touchVisible = await mob.evaluate(() => {
  const el = document.getElementById('touch-controls');
  return { hasShow: el.classList.contains('show'), rect: el.getBoundingClientRect().toJSON(), canvas: document.getElementById('game').getBoundingClientRect().toJSON() };
});
console.log('TOUCH UI:', JSON.stringify(touchVisible));
const btn = mob.locator('[data-key="punch"]');
const bb = await btn.boundingBox();
console.log('PUNCH BTN BOX:', bb);
if (bb) {
  await mob.touchscreen.tap(bb.x + bb.width / 2, bb.y + bb.height / 2);
  await mob.waitForTimeout(200);
  console.log('TOUCH PUNCH STATE:', await mob.evaluate(() => ({ state: window.__cc.game.fighters[0].state, meter: window.__cc.game.fighters[0].meter })));
}
await mob.screenshot({ path: '/tmp/opencode/v-mobile.png' });

console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

