// ---------------------------------------------------------------- scene flow

function startSelect(mode) {
  game.mode = mode;
  game.scene = 'select';
  game.howto = false;
  game.paused = false;
  game.select = { step: 0, cursors: [0, 4], picked: [null, null], rouletteT: 0, cpuDoneT: 0 };
  game.time = 0;
  audio.playTrack('menu');
  audio.confirm();
}

function confirmPick() {
