import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];

for (const [name, vp] of [['portrait', { width: 390, height: 844 }], ['landscape', { width: 844, height: 390 }]]) {
  const page = await browser.newPage({ viewport: vp, hasTouch: true, isMobile: true });
  page.on('pageerror', (e) => errors.push(name + ' ' + e.message));
  await page.goto('http://localhost:3002/?touch=1', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.evaluate(() => window.__cc.startMatchup(4, 7, 'local'));
  await page.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });
  const info = await page.evaluate(() => {
    const mb = document.getElementById('mute-btn');
    const r = mb.getBoundingClientRect();
    const c = document.getElementById('game').getBoundingClientRect();
    return {
      text: mb.textContent, shown: mb.classList.contains('show'),
      box: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
      canvas: { x: Math.round(c.x), y: Math.round(c.y), w: Math.round(c.width), h: Math.round(c.height) },
      overlap: !(r.right <= c.left || r.left >= c.right || r.bottom <= c.top || r.top >= c.bottom),
    };
  });
  console.log(name.toUpperCase(), JSON.stringify(info));
  // tap mute and verify
  const bb = await page.locator('#mute-btn').boundingBox();
  await page.touchscreen.tap(bb.x + bb.width / 2, bb.y + bb.height / 2);
  await page.waitForTimeout(300);
  console.log(name, 'AFTER TAP:', await page.evaluate(() => document.getElementById('mute-btn').textContent));
  await page.screenshot({ path: `/tmp/opencode/v-${name}-final.png` });
  await page.close();
}
console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

