import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(60000);
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(500);

const c = await page.evaluate(() => document.getElementById('game').getBoundingClientRect().toJSON());
const click = async (cx, cy) => {
  await page.mouse.click(c.x + (cx / 480) * c.width, c.y + (cy / 270) * c.height);
  await page.waitForTimeout(250);
};

// Title click 1 PLAYER
await click(240, 142);
console.log('CLICK 1P:', await page.evaluate(() => ({ scene: window.__cc.game.scene, mode: window.__cc.game.mode })));

// Click a roster cell twice to pick
await click(16 + 2 * 54 + 25, 52 + 29);
console.log('CLICK CELL cursor:', await page.evaluate(() => window.__cc.game.select.cursors[0]));
await click(16 + 2 * 54 + 25, 52 + 29);
console.log('CLICK CELL confirm:', await page.evaluate(() => ({ step: window.__cc.game.select.step, picked: window.__cc.game.select.picked })));
await page.waitForFunction(() => window.__cc.game.scene === 'fight', null, { timeout: 120000 });
console.log('POINTER MATCH:', await page.evaluate(() => ({ names: window.__cc.game.fighters.map(f => f.char.name), picked: window.__cc.game.select.picked })));
await page.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });

// Pause and click restart
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
await click(240, 92 + 22 + 9);
console.log('CLICK RESTART:', await page.evaluate(() => ({ paused: window.__cc.game.paused, lock: window.__cc.game.fightLock })));
await page.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });

// Force result and click REMATCH
await page.evaluate(() => {
  const g = window.__cc.game;
  g.result = { winner: g.fighters[0], winnerIdx: 0, rounds: [2, 0], perfect: false };
  g.scene = 'result';
  g.resultIndex = 0;
});
await page.waitForTimeout(250);
await click(20 + 70, 238 + 11);
console.log('CLICK REMATCH:', await page.evaluate(() => ({ scene: window.__cc.game.scene, round: window.__cc.game.round, names: window.__cc.game.fighters.map(f => f.char.name) })));

// Force result and click TITLE
await page.evaluate(() => {
  const g = window.__cc.game;
  g.result = { winner: g.fighters[0], winnerIdx: 0, rounds: [2, 0], perfect: false };
  g.scene = 'result';
});
await page.waitForTimeout(250);
await click(20 + 2 * 150 + 70, 238 + 11);
console.log('CLICK TITLE:', await page.evaluate(() => window.__cc.game.scene));

