import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
const res = await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(700);
const info = await page.evaluate(async () => {
  const m = await import('./js/characters.js');
  return {
    roster: m.ROSTER.map(r => `${r.name} — ${r.title}`),
    stages: Object.keys(m.STAGE_INFO),
    muteBtn: !!document.getElementById('mute-btn'),
    scene: window.__cc.game.scene,
    diff: window.__cc.game.diff,
  };
});
console.log('HTTP', res.status());
console.log('ROSTER', info.roster.length);
info.roster.forEach((r, i) => console.log(' ', i + 1, r));
console.log('STAGES', info.stages.join(', '));
console.log('MUTE BUTTON', info.muteBtn, '| SCENE', info.scene);
// difficulty cycle
for (let i = 0; i < 3; i++) {
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Enter');
  console.log('DIFF AFTER ENTER', await page.evaluate(() => window.__cc.game.diff));
}
// full start
await page.evaluate(() => window.__cc.startMatchup(10, 4, 'cpu'));
await page.waitForFunction(() => window.__cc.game.fightLock === 0, null, { timeout: 60000 });
console.log('MATCH', await page.evaluate(() => {
  const g = window.__cc.game;
  return { scene: g.scene, names: g.fighters.map(f => f.char.name), stage: g.stage, timer: g.timer };
}));
console.log('ERRORS', errors.length ? errors.join('\n') : 'none');
await browser.close();
EOF
